SPLITS = {"train": 0, "validation": 1, "test": 2}


def restore_unicode(value: str) -> str:
    # Keep this source ASCII-safe across Windows editors and restore escaped Hindi text.
    try:
        value = value.encode("latin-1").decode("utf-8")
    except UnicodeError:
        pass
    value = re.sub(r"\\u([0-9a-fA-F]{4})", lambda match: chr(int(match.group(1), 16)), value)
    return re.sub(r"\\u(?=[^0-9a-fA-F])", "", value)


def main():
    for split, variant in SPLITS.items():
        output = ROOT / f"{split}.csv"
        rows = []
        index = 0
        for category, labels in EXAMPLES.items():
            for label, languages in labels.items():
                for language in LANGUAGES:
                    message = restore_unicode(languages[language][variant])
                    index += 1
                    rows.append({
                        "text": message, "label": label, "category": category,
                        "language": language, "source_type": "synthetic",
                        "source_id": f"synthetic-{split}-{index:03d}",
                    })
        with output.open("w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=rows[0].keys())
            writer.writeheader()
            writer.writerows(rows)
        print(f"Wrote {len(rows)} explicitly synthetic examples to {output.name}")


if __name__ == "__main__":
    main()
